    {
      "path": "tools.linear.list_comments",
      "description": "List comments on a Linear issue, project, initiative, document, project milestone, or project/initiative status update. Provide exactly one of `issueId`, `projectId`, `initiativeId`, `documentId`, `milestoneId`, or `statusUpdateId`. `statusUpdateType` applies only to `statusUpdateId`; omit it for every other parent. For issues, projects, and initiatives this returns both top-level discussion threads and inline description comments. Inline (anchored) comments carry a non-null `quotedText` set to the snippet of description text they reference. Returned comments include `author` and nullable `onBehalfOf`; when set, `onBehalfOf` identifies the user the agent author acted for. Files uploaded in comment bodies are returned in `attachments` with titles and download URLs, not issue attachment IDs. Signed upload URLs expire after five minutes; call list_comments again to refresh them. Download documents using these URLs and process them with your own file tools.",
      "signature": "tools.linear.list_comments({
  /** Maximum number of results to return per page. @default 50 @maximum 250 */
  limit?: number,
  /** Omit for the first page. To continue, pass the previous response's cursor when hasNextPage is true */
  cursor?: string,
  /** Timestamp to sort results by: creation time or last update time. @default "updatedAt" */
  orderBy?: "createdAt" | "updatedAt",
  /**
   * Issue ID or identifier (e.g., LIN-123). P-prefixed identifiers (e.g., P-ENG-123) are projects, not issues (provide exactly one parent)
   */
  issueId?: string,
  /** Project name, ID, identifier (e.g., P-ENG-123), or slug (provide exactly one parent) */
  projectId?: string,
  /** Initiative name, ID, identifier (e.g., I-123), or slug (provide exactly one parent) */
  initiativeId?: string,
  /** Document ID or slug (provide exactly one parent) */
  documentId?: string,
  /** Milestone UUID (provide exactly one parent). Resolve milestone names via `list_milestones` first. */
  milestoneId?: string,
  /** Status update UUID (provide exactly one parent). Resolve status updates via `get_status_updates` first. */
  statusUpdateId?: string,
  /**
   * Set only together with `statusUpdateId`; omit for issue, project, initiative, document, and milestone comments. Type of status update named by `statusUpdateId`, as returned by `get_status_updates`. Omit to check both project and initiative status updates.
   */
  statusUpdateType?: "project" | "initiative",
}): Promise<unknown>"
    },
    {
      "path": "tools.linear.save_comment",
      "description": "Create or update a comment on a Linear issue, project, initiative, document, project milestone, or project/initiative status update. If `id` is provided, updates the existing comment; otherwise creates a new one. To start a new thread, pass `body` and exactly one of `issueId`, `projectId`, `initiativeId`, `documentId`, `milestoneId`, or `statusUpdateId` (`statusUpdateType` applies only to `statusUpdateId`; omit it for every other parent) — comments on issues/projects/initiatives become top-level discussion threads; comments on documents/milestones become description comments. A status update holds a single thread, so a comment on an update that already has one is added to it as a reply. To reply to an existing thread, pass `parentId` and `body`; the reply inherits the parent's thread type, so no entity reference is needed. Parent reference fields are ignored when `id` or `parentId` is provided (`statusUpdateType` is rejected instead).",
      "signature": "tools.linear.save_comment({
  /** Comment ID. If provided, updates the existing comment */
  id?: string,
  /**
   * Issue ID or identifier (e.g., LIN-123). P-prefixed identifiers (e.g., P-ENG-123) are projects, not issues (provide exactly one parent)
   */
  issueId?: string,
  /** Project name, ID, identifier (e.g., P-ENG-123), or slug (provide exactly one parent) */
  projectId?: string,
  /** Initiative name, ID, identifier (e.g., I-123), or slug (provide exactly one parent) */
  initiativeId?: string,
  /** Document ID or slug (provide exactly one parent) */
  documentId?: string,
  /** Milestone UUID (provide exactly one parent). Resolve milestone names via `list_milestones` first. */
  milestoneId?: string,
  /** Status update UUID (provide exactly one parent). Resolve status updates via `get_status_updates` first. */
  statusUpdateId?: string,
  /**
   * Set only together with `statusUpdateId`; omit for issue, project, initiative, document, and milestone comments. Type of status update named by `statusUpdateId`, as returned by `get_status_updates`. Omit to check both project and initiative status updates.
   */
  statusUpdateType?: "project" | "initiative",
  /** Parent comment ID (for replies, only when creating) */
  parentId?: string,
  /**
   * Content as Markdown. Do not escape the string — use literal newlines and special characters, not escape sequences. To mention a user, use @displayName (e.g., @johndoe). To embed an image or file, upload it with prepare_file_upload and insert the returned markdown
   */
  body: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.linear.delete_comment",
      "description": "Delete a Linear comment. Inline description comments (those with non-null `quotedText`) anchor a mark in the editor, so their root cannot be deleted — delete the replies individually or resolve the thread instead.",
      "signature": "tools.linear.delete_comment({
  /** Comment ID */
  id: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.linear.delete_diff_comment",
      "description": "Delete a comment or persisted draft from a Linear diff",
      "signature": "tools.linear.delete_diff_comment({
  /** Submitted diff comment ID to delete. @minLength 1 */
  commentId?: string,
  /** Persisted diff comment draft ID to delete. @minLength 1 */
  draftId?: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.linear.list_agent_skills",
      "description": "List Linear Agent skills available to the authenticated user.",
      "signature": "tools.linear.list_agent_skills({
  /** Maximum number of results to return per page. @default 50 @maximum 250 */
  limit?: number,
  /** Omit for the first page. To continue, pass the previous response's cursor when hasNextPage is true */
  cursor?: string,
  /** Timestamp to sort results by: creation time or last update time. @default "updatedAt" */
  orderBy?: "createdAt" | "updatedAt",
}): Promise<unknown>"
    },
    {
      "path": "tools.linear.list_customers",
      "description": "List customers in the user's Linear workspace",
      "signature": "tools.linear.list_customers({
  /** Maximum number of results to return per page. @default 50 @maximum 250 */
  limit?: number,
  /** Omit for the first page. To continue, pass the previous response's cursor when hasNextPage is true */
  cursor?: string,
  /** Timestamp to sort results by: creation time or last update time. @default "updatedAt" */
  orderBy?: "createdAt" | "updatedAt",
  /** Search customer name */
  query?: string,
  /** Exact customer domain (case-insensitive); combined with other filters. @minLength 1 */
  domain?: string,
